namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}}
bool ScriptSession::inventoryFlag(const UnitState& u,const char* field){bool deathDrop=std::string_view(field)=="DataB";for(auto [ability,level]:u.abilities)if(level>0){auto& info=inventoryAbilityInfo(ability,unsigned(level));if(!info.inventory || (!deathDrop && !inventoryAbilityReady(u.owner,info)))continue;auto value=definitions().number(ability,"AbilityData",std::string(field)+std::to_string(level));if(value!=0 && value!=1)throw std::runtime_error("Invalid source inventory permission");if(value!=0)return true;}return false;}
const std::vector<std::uint32_t>& ScriptSession::itemAbilities(std::uint32_t type){
    if(auto found=itemPassives_.find(type);found!=itemPassives_.end())return found->second;std::vector<std::uint32_t> result;std::stringstream input(definitions().field(type,"ItemData","abilList"));std::string entry;while(std::getline(input,entry,',')){auto first=entry.find_first_not_of(" \t\"");if(first==std::string::npos)continue;entry=entry.substr(first,entry.find_last_not_of(" \t\"")-first+1);if(entry=="_" || entry=="-")continue;if(entry.size()!=4 || !definitions().ability(ObjectData::code(entry)) || result.size()>=256)throw std::runtime_error("Invalid source item ability list: "+ObjectData::name(type));result.push_back(ObjectData::code(entry));}return itemPassives_.emplace(type,std::move(result)).first->second;
}
std::vector<std::uint32_t> ScriptSession::itemActiveAbilities(std::uint32_t type){std::vector<std::uint32_t> result;for(auto ability:itemAbilities(type))if(!equipmentInfo(ability,1) && passiveInfo(ability,1).kind==PassiveKind::Unsupported)result.push_back(ability);return result;}
namespace {bool damageOrb(std::string_view code){return code=="AIfb" || code=="AIob" || code=="AIcb" || code=="AIpb" || code=="AIlb" || code=="AIsb";}}
const EquipmentBonuses* ScriptSession::equipmentInfo(std::uint32_t ability,unsigned level){
    auto key=std::pair{ability,level};if(auto found=equipmentInfo_.find(key);found!=equipmentInfo_.end())return found->second?&*found->second:nullptr;auto& data=definitions();std::optional<EquipmentBonuses> value;auto code=data.field(ability,"AbilityData","code",ObjectData::name(ability));if(level && data.ability(ability) && (damageOrb(code) || code=="AIab" || code=="Aamk" || code=="AIat" || code=="AIde" || code=="AIas" || code=="AIml" || code=="AImm" || code=="AIms" || code=="Arel" || code=="AIrm" || code=="AIsr" || code=="AIva" || code=="Amim" || code=="Ault" || code=="AIsi" || code=="AIdd")){
        value.emplace();auto& b=*value;auto field=[&](const char* name){return data.number(ability,"AbilityData",std::string(name)+std::to_string(level));};if(code=="AIab" || code=="Aamk")b.attributes={field("DataC"),field("DataA"),field("DataB")};else if(code=="AIat" || damageOrb(code))b.damage=field("DataA");else if(code=="AIde")b.armor=field("DataA");else if(code=="AIas")b.attackSpeed=field("DataA");else if(code=="AIsi")b.sight=field("DataA");else if(code=="AIml")b.health=field("DataA");else if(code=="AImm")b.mana=field("DataA");else if(code=="AIms"){auto move=field("DataA");b.movement=std::max(0.f,move);b.movePenalty=std::min(0.f,move);}else if(code=="Arel")b.healthRegen=field("DataA");else if(code=="AIrm")b.manaRegen=field("DataA");else if(code=="AIsr"){b.damagePercent=field("DataA");b.spellReduction=field("DataB");}else if(code=="AIva")b.vampiric=field("DataA");else if(code=="Amim")b.magicImmune=true;else if(code=="Ault")b.ultravision=true;else if(code=="AIdd"){auto move=field("DataC"),attack=field("DataD");if(!std::isfinite(move) || !std::isfinite(attack) || move<0 || move>10 || attack<0 || attack>10)throw std::runtime_error("Passive defend speed factors outside supported range");if(move>0){b.defendMoveReduction=std::max(0.f,1-move);b.defendMoveBonus=std::max(0.f,move-1);}b.defendAttackReduction=attack;}
        for(auto part:b.attributes)if(!std::isfinite(part) || std::abs(part)>1000000)throw std::runtime_error("Equipment attribute outside supported range");for(auto part:{b.health,b.mana,b.damage,b.damagePercent,b.armor,b.attackSpeed,b.movement,b.movePenalty,b.healthRegen,b.manaRegen,b.spellReduction,b.vampiric,b.sight})if(!std::isfinite(part) || std::abs(part)>1000000)throw std::runtime_error("Equipment modifier outside supported range");if(b.spellReduction<0 || b.spellReduction>1 || b.manaRegen<-1 || b.vampiric<0)throw std::runtime_error("Equipment reduction or recovery factor outside supported range");
    }auto found=equipmentInfo_.emplace(key,std::move(value)).first;return found->second?&*found->second:nullptr;
}
void ScriptSession::refreshEquipment(UnitState& u){
    if(!u.handle || u.removing)return;refreshSpellBooks(u);for(auto it=u.criticalFailures.begin();it!=u.criticalFailures.end();){bool retained=u.abilities.contains(it->first);if(!retained)for(auto id:u.inventory)if(id && alive(id,NativeKind::Item) && items_.at(id)->holder==u.handle){const auto& abilities=itemAbilities(items_.at(id)->type);if(std::find(abilities.begin(),abilities.end(),it->first)!=abilities.end()){retained=true;break;}}if(retained)++it;else it=u.criticalFailures.erase(it);}refreshEngineering(u);refreshPhoenixFire(u);refreshRestoration(u);bool stack=gameplayNumber("MoveSpeedBonusesStack",0)!=0;auto add=[&](EquipmentBonuses& to,const EquipmentBonuses& from){for(unsigned i=0;i<3;++i)to.attributes[i]+=from.attributes[i];to.health+=from.health;to.mana+=from.mana;to.damage+=from.damage;to.damagePercent+=from.damagePercent;to.armor+=from.armor;to.attackSpeed+=from.attackSpeed;to.movement=stack?to.movement+from.movement:std::max(to.movement,from.movement);to.movePenalty=stack?to.movePenalty+from.movePenalty:std::min(to.movePenalty,from.movePenalty);to.sight+=from.sight;to.healthRegen+=from.healthRegen;to.manaRegen+=from.manaRegen;to.spellReduction=std::max(to.spellReduction,from.spellReduction);to.vampiric=std::max(to.vampiric,from.vampiric);to.defendMoveReduction=std::max(to.defendMoveReduction,from.defendMoveReduction);to.defendMoveBonus=std::max(to.defendMoveBonus,from.defendMoveBonus);to.defendAttackReduction=std::max(to.defendAttackReduction,from.defendAttackReduction);to.magicImmune|=from.magicImmune;to.ultravision|=from.ultravision;};EquipmentBonuses next,inventory;if(u.engineering)next.damage+=u.engineering->damage;if(u.unitForm && u.unitForm->active && u.unitForm->spell.kind==SpellKind::RoboGoblin){next.attributes[0]+=u.unitForm->spell.roboStrength;next.armor+=u.unitForm->spell.roboArmor;}
    auto enabled=[&](std::uint32_t ability,unsigned level,const EquipmentBonuses& value){auto code=definitions().field(ability,"AbilityData","code",ObjectData::name(ability));if(!value.ultravision && code!="AIdd" && code!="AIsi" && !damageOrb(code))return true;auto available=config_.players[u.owner].abilityAvailable.find(ability);if(available!=config_.players[u.owner].abilityAvailable.end() && !available->second)return false;for(auto [type,count]:passiveInfo(ability,level).prerequisites)if(techCount(u.owner,type,false)<count)return false;return true;};for(auto [ability,level]:u.abilities)if(level>0)if(auto value=equipmentInfo(ability,unsigned(level));value && enabled(ability,unsigned(level),*value))add(next,*value);if(u.illusion)inventory=u.inventoryBonuses;else if(inventoryFlag(u,"DataC"))for(auto id:u.inventory)if(id && alive(id,NativeKind::Item) && items_.at(id)->holder==u.handle)for(auto ability:itemAbilities(items_.at(id)->type))if(auto value=equipmentInfo(ability,1);value && enabled(ability,1,*value))add(inventory,*value);u.inventoryBonuses=inventory;add(next,inventory);
    if(u.illusion){if(gameplayNumber("IllusionsGetAttackBonus",1)==0){next.damage=0;next.damagePercent=0;}if(gameplayNumber("IllusionsGetAttackSpeedBonus",1)==0){next.attackSpeed=0;next.defendAttackReduction=0;}if(gameplayNumber("IllusionsGetDefenseBonus",1)==0)next.armor=0;if(gameplayNumber("IllusionsGetMoveSpeedBonus",1)==0){next.movement=next.movePenalty=0;next.defendMoveReduction=next.defendMoveBonus=0;}}
    if(next==u.equipment)return;for(auto part:{next.health,next.mana,next.damage,next.damagePercent,next.armor,next.attackSpeed,next.movement,next.movePenalty,next.healthRegen,next.manaRegen,next.sight})if(!std::isfinite(part) || std::abs(part)>100000000)throw std::runtime_error("Combined equipment budget exceeded");auto old=u.equipment;auto previous=u.appliedHeroStats;float maximum=number(u.maxLife),life=number(u.life),manaMaximum=number(u.maxMana),mana=number(u.mana),move=next.movement+next.movePenalty-old.movement-old.movePenalty;u.equipment=next;refreshHero(u);float hp=next.health-old.health+(u.appliedHeroStats[0]-previous[0])*gameplayNumber("StrHitPointBonus",25),mp=next.mana-old.mana+(u.appliedHeroStats[2]-previous[2])*gameplayNumber("IntManaBonus",15);u.maxLife=real(std::max(1.f,maximum+hp));u.maxMana=real(std::max(0.f,manaMaximum+mp));u.life=real(life>0?std::clamp(life/std::max(1.f,maximum)*number(u.maxLife),1.f,number(u.maxLife)):0.f);u.mana=real(std::clamp(manaMaximum>0?mana/manaMaximum*number(u.maxMana):mana,0.f,number(u.maxMana)));u.moveSpeed=real(std::max(0.f,number(u.moveSpeed)+move));++fogRevision_;
}
void ScriptSession::permanentItem(std::uint32_t id,std::uint32_t ability){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(u->removing || number(u->life)<=0)return;auto code=definitions().field(ability,"AbilityData","code",ObjectData::name(ability));auto field=[&](const char* name){return definitions().number(ability,"AbilityData",std::string(name)+"1");};float amount=field("DataA");if(code=="AIaa"){double next=double(u->permanentDamage)+amount;if(!std::isfinite(next) || std::abs(next)>100000000)throw std::runtime_error("Permanent attack damage outside supported range");u->permanentDamage=float(next);return;}if(code=="AImi"){u->maxLife=real(number(u->maxLife)+amount);unitLife(runtime_.handle("unit",id),real(number(u->life)+amount));return;}if(!u->hero)throw std::runtime_error("Permanent attribute, level or experience item requires a hero");
    if(code=="AIlm" || code=="AIem"){if(amount<0 || amount>INT_MAX || amount!=std::floor(amount))throw std::runtime_error("Permanent level or experience amount outside supported range");if(code=="AIem")heroExperience(id,int(std::min(std::int64_t(INT_MAX),std::int64_t(u->experience)+std::int64_t(amount))));else {auto& levels=heroThresholds();auto target=size_t(std::min(std::int64_t(levels.size()),std::int64_t(u->level)+std::int64_t(amount)));if(target>size_t(u->level))heroExperience(id,levels[target-1]);}return;}
    if(code!="AIam" && code!="AIim" && code!="AIsm" && code!="AIxm")throw std::runtime_error("Permanent item consumer is not implemented: "+code);std::array<float,3> bonus{field("DataC"),amount,field("DataB")};for(unsigned i=0;i<3;++i){if(!std::isfinite(bonus[i]) || bonus[i]<0 || bonus[i]>1000000)throw std::runtime_error("Permanent item attribute outside supported range");u->heroAttributes[i]+=bonus[i];}refreshHero(*u);
}
